import { useState } from "react";

function PostForm({ token, onPostAdded, categoryId }) {
    const [title, setTitle] = useState("");
    const [content, setContent] = useState("");
    const [error, setError] = useState("");
    const [loading, setLoading] = useState(false);

    const handleSubmit = async (e) => {
        e.preventDefault();

        if (!title || !content || !categoryId) {
            setError("Заповніть всі поля і оберіть категорію");
            return;
        }

        setLoading(true);
        try {
            const res = await fetch("http://localhost:5000/api/posts", {
                method: "POST",
                headers: {
                    "Content-Type": "application/json",
                    Authorization: `Bearer ${token}`,
                },
                body: JSON.stringify({ title, content, category_id: categoryId }),
            });

            const data = await res.json();

            if (!res.ok) {
                setError(data.message || "Помилка при створенні поста");
            } else {
                setTitle("");
                setContent("");
                setError("");
                if (onPostAdded) onPostAdded(); // оновлюємо список постів
            }
        } catch (err) {
            console.error(err);
            setError("Помилка при запиті до сервера");
        } finally {
            setLoading(false);
        }
    };

    return (
        <div className="card-gradient rounded-2xl p-6 shadow-xl">
            <div className="flex items-center mb-6">
                <h3 className="text-xl font-bold gradient-text">Створити пост</h3>
            </div>

            {error && (
                <div className="mb-4 p-3 bg-red-50 border-l-4 border-red-500 rounded-lg">
                    <p className="text-red-700 text-sm font-medium">{error}</p>
                </div>
            )}

            <form onSubmit={handleSubmit} className="space-y-4">
                <div>
                    <input
                        type="text"
                        placeholder="Заголовок поста..."
                        value={title}
                        onChange={(e) => setTitle(e.target.value)}
                        className="input-field"
                    />
                </div>

                <div>
                    <textarea
                        placeholder="Що у вас на думці?..."
                        value={content}
                        onChange={(e) => setContent(e.target.value)}
                        rows={4}
                        className="input-field min-h-[120px] resize-none"
                    />
                </div>

                <button
                    type="submit"
                    disabled={loading || !categoryId}
                    className="btn-primary w-full disabled:opacity-50 disabled:cursor-not-allowed"
                >
                    {loading ? 'Публікуємо...' : 'Опублікувати'}
                </button>
            </form>
        </div>
    );
}

export default PostForm;
